import React, { useState, useEffect } from 'react';
import './CustomerList.css';

const CustomerList = ({ onSelect }) => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch customers from backend
  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8080/api/customers');
      if (!response.ok) {
        throw new Error('Failed to fetch customers');
      }
      const data = await response.json();
      setCustomers(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (customerId) => {
    if (window.confirm('Are you sure you want to delete this customer?')) {
      try {
        const response = await fetch(`http://localhost:8080/api/customers/${customerId}`, {
          method: 'DELETE',
        });
        
        if (response.ok) {
          setCustomers(customers.filter(customer => customer.id !== customerId));
          alert('Customer deleted successfully!');
        } else {
          throw new Error('Failed to delete customer');
        }
      } catch (err) {
        alert('Error deleting customer: ' + err.message);
      }
    }
  };

  if (loading) {
    return (
      <div className="customer-list-container">
        <div className="loading-section">
          <div className="spinner"></div>
          <p>Loading customers...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="customer-list-container">
        <div className="error-section">
          <h3>❌ Error loading customers</h3>
          <p>{error}</p>
          <button onClick={fetchCustomers} className="retry-button">
            🔄 Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="customer-list-container">
      <div className="list-header">
        <h2>📋 Customer List</h2>
        <div className="header-actions">
          <button onClick={fetchCustomers} className="refresh-button">
            🔄 Refresh
          </button>
          <span className="customer-count">
            Total: {customers.length}
          </span>
        </div>
      </div>

      {customers.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">📝</div>
          <h3>No customers yet</h3>
          <p>Register your first customer to get started!</p>
        </div>
      ) : (
        <div className="customers-grid">
          {customers.map((customer) => (
            <div key={customer.id} className="customer-card">
              <div className="customer-header">
                <div className="customer-id">#{customer.id}</div>
                <div className={`customer-type-badge ${customer.customerType?.toLowerCase()}`}>
                  {customer.customerType || 'REGULAR'}
                </div>
              </div>
              
              <div className="customer-info">
                <h3 className="customer-name">
                  {customer.firstName} {customer.lastName}
                </h3>
                <div className="customer-details">
                  <div className="detail-row">
                    <span className="detail-label">📧</span>
                    <span className="detail-value">{customer.email}</span>
                  </div>
                  <div className="detail-row">
                    <span className="detail-label">📞</span>
                    <span className="detail-value">{customer.phoneNumber}</span>
                  </div>
                </div>
              </div>
              
              <div className="customer-actions">
                <button
                  onClick={() => onSelect(customer.id)}
                  className="action-btn view-btn"
                  title="View Details"
                >
                  👁️ View
                </button>
                <button
                  onClick={() => handleDelete(customer.id)}
                  className="action-btn delete-btn"
                  title="Delete Customer"
                >
                  🗑️ Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default CustomerList;
